import{_ as a}from"./chunks/system-management.G53wYALY.js";import{_ as r,o as e,c as o,a2 as l}from"./chunks/framework.Cd7uensT.js";const m=JSON.parse('{"title":"系统管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/system-management.md","filePath":"guide/features/system-management.md","lastUpdated":1784623729000}'),d={name:"guide/features/system-management.md"};function i(n,t,s,h,g,b){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="系统管理" tabindex="-1">系统管理 <a class="header-anchor" href="#系统管理" aria-label="Permalink to &quot;系统管理&quot;">​</a></h1><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h2><p>用户管理用于管理系统用户账号和权限。</p><p><img src="'+a+'" alt="系统管理概览"></p><h3 id="用户状态" tabindex="-1">用户状态 <a class="header-anchor" href="#用户状态" aria-label="Permalink to &quot;用户状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><strong>正常</strong></td><td>用户可正常登录系统并使用相应权限功能</td></tr><tr><td><strong>待审核</strong></td><td>新注册用户，等待管理员审核通过后方可登录</td></tr><tr><td><strong>已禁用</strong></td><td>账号被管理员禁用，无法登录系统</td></tr></tbody></table><h3 id="审核流程" tabindex="-1">审核流程 <a class="header-anchor" href="#审核流程" aria-label="Permalink to &quot;审核流程&quot;">​</a></h3><p>用户注册审核流程如下：</p><ol><li><strong>用户注册</strong>：新用户通过注册页面提交账号信息</li><li><strong>待审核状态</strong>：注册成功后，账号自动进入「待审核」状态</li><li><strong>管理员审核</strong>：管理员在「用户管理」页面查看待审核用户列表</li><li><strong>审核操作</strong>：管理员可「通过」或「驳回」注册申请，驳回需填写原因</li><li><strong>结果通知</strong>： <ul><li>审核通过：用户收到通知，账号状态变更为「正常」，可登录系统</li><li>审核驳回：用户收到通知及驳回原因，可根据原因修改后重新提交注册</li></ul></li></ol><h3 id="角色权限" tabindex="-1">角色权限 <a class="header-anchor" href="#角色权限" aria-label="Permalink to &quot;角色权限&quot;">​</a></h3><p>系统采用 RBAC（基于角色的访问控制）权限模型：</p><table tabindex="0"><thead><tr><th>角色</th><th>权限范围</th></tr></thead><tbody><tr><td><strong>管理员</strong></td><td>全部功能，包括系统设置、用户管理、数据管理、所有模块的增删改查</td></tr><tr><td><strong>运维人员</strong></td><td>设备管理（含导入导出、端口管理、接线管理）、工单处理（接单、处理、完成）</td></tr><tr><td><strong>普通用户</strong></td><td>查看权限（查看设备、工单、仪表盘等），可创建工单</td></tr></tbody></table><h3 id="角色管理" tabindex="-1">角色管理 <a class="header-anchor" href="#角色管理" aria-label="Permalink to &quot;角色管理&quot;">​</a></h3><ul><li><strong>自定义角色</strong>：支持管理员自定义角色，为不同岗位配置专属权限组合</li><li><strong>权限粒度</strong>：权限控制到页面级和操作级（新增、编辑、删除、查看、导入、导出）</li><li><strong>角色分配</strong>：在用户编辑页面勾选角色，支持一个用户拥有多个角色</li></ul><h2 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h2><p>系统设置用于配置系统全局参数，包含「基本设置」「邮件服务」「关于系统」三个标签页。</p><h3 id="基本设置" tabindex="-1">基本设置 <a class="header-anchor" href="#基本设置" aria-label="Permalink to &quot;基本设置&quot;">​</a></h3><p>基本设置包含站点信息、公司信息、安全设置等通用配置。</p><h4 id="站点信息" tabindex="-1">站点信息 <a class="header-anchor" href="#站点信息" aria-label="Permalink to &quot;站点信息&quot;">​</a></h4><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>站点名称</strong></td><td>系统浏览器标签页标题和页面左上角显示的名称</td></tr><tr><td><strong>Logo</strong></td><td>系统左上角显示的 Logo 图片，建议尺寸 120×40px，支持 PNG/SVG 格式</td></tr></tbody></table><h4 id="安全设置" tabindex="-1">安全设置 <a class="header-anchor" href="#安全设置" aria-label="Permalink to &quot;安全设置&quot;">​</a></h4><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>空闲超时</strong></td><td>用户无操作后自动退出登录的时间，可选范围：15分钟、30分钟、60分钟、永不超时</td></tr><tr><td><strong>背景图片</strong></td><td>登录页的背景图片，支持 JPG/PNG 格式</td></tr><tr><td><strong>维护模式</strong></td><td>开启后系统仅管理员可登录，其他用户访问时显示维护提示页面</td></tr><tr><td><strong>登录限制</strong></td><td>可限制指定 IP 段或仅允许内网 IP 访问系统登录页</td></tr></tbody></table><h3 id="邮件服务-管理员专属" tabindex="-1">邮件服务（管理员专属） <a class="header-anchor" href="#邮件服务-管理员专属" aria-label="Permalink to &quot;邮件服务（管理员专属）&quot;">​</a></h3><blockquote><p>v2.3.0 新增，仅管理员可见此标签页。</p></blockquote><p>邮件服务用于配置 SMTP 邮件发送，支持发送验证码邮件、测试邮件等功能。</p><h4 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h4><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>SMTP 服务器</strong></td><td>邮件发送服务器地址（如 smtp.example.com）</td></tr><tr><td><strong>端口</strong></td><td>SMTP 服务端口（465/587/25 等）</td></tr><tr><td><strong>加密方式</strong></td><td>SSL/TLS 加密方式</td></tr><tr><td><strong>发件人邮箱</strong></td><td>发件人邮箱地址</td></tr><tr><td><strong>发件人名称</strong></td><td>邮件发件人显示名称</td></tr><tr><td><strong>SMTP 用户名</strong></td><td>邮箱登录用户名</td></tr><tr><td><strong>SMTP 密码</strong></td><td>邮箱登录密码或授权码</td></tr></tbody></table><h4 id="操作说明" tabindex="-1">操作说明 <a class="header-anchor" href="#操作说明" aria-label="Permalink to &quot;操作说明&quot;">​</a></h4><ol><li>进入「系统管理」→「系统设置」→「邮件服务」标签</li><li>填写 SMTP 服务器配置信息</li><li>点击「保存」完成配置</li><li>（可选）点击「发送测试邮件」验证配置是否生效</li></ol><h3 id="关于系统" tabindex="-1">关于系统 <a class="header-anchor" href="#关于系统" aria-label="Permalink to &quot;关于系统&quot;">​</a></h3><p>关于系统页面提供系统版本信息和相关工具。</p><h4 id="系统信息" tabindex="-1">系统信息 <a class="header-anchor" href="#系统信息" aria-label="Permalink to &quot;系统信息&quot;">​</a></h4><ul><li><strong>系统名称</strong>：IDC 设备资产管理系统</li><li><strong>当前版本</strong>：显示当前运行的版本号</li><li><strong>部署环境</strong>：显示是否运行在 Docker 容器中</li></ul><h4 id="在线更新" tabindex="-1">在线更新 <a class="header-anchor" href="#在线更新" aria-label="Permalink to &quot;在线更新&quot;">​</a></h4><blockquote><p>v2.3.2 新增。</p></blockquote><p>点击「检查更新」按钮，系统自动检测是否有新版本可用：</p><ul><li><strong>已是最新</strong>：绿色标识提示已是最新版本</li><li><strong>发现新版本</strong>：显示当前版本与最新版本对比，并提供更新指引 <ul><li>非 Docker 环境：显示终端命令提示（<code>cd 项目路径 &amp;&amp; node update.js</code>），支持一键复制</li><li>Docker 环境：提示拉取最新镜像后重建容器</li></ul></li><li>更新日志区域展示版本发布说明</li></ul><h4 id="开源许可" tabindex="-1">开源许可 <a class="header-anchor" href="#开源许可" aria-label="Permalink to &quot;开源许可&quot;">​</a></h4><blockquote><p>v2.3.2 新增。</p></blockquote><p>点击「开源许可」按钮，可查看系统前后端所有依赖包的开源许可信息：</p><ul><li>按许可类型分组统计（MIT、Apache-2.0、ISC 等）</li><li>列表展示：依赖名称、版本、许可类型、运行/开发分类、项目主页</li><li>支持分页浏览</li></ul><h3 id="操作说明-1" tabindex="-1">操作说明 <a class="header-anchor" href="#操作说明-1" aria-label="Permalink to &quot;操作说明&quot;">​</a></h3><ol><li>进入「系统管理」→「系统设置」页面</li><li>通过左侧标签导航切换不同设置模块</li><li>修改配置项后点击「保存」按钮</li><li>部分设置（如站点名称、Logo、空闲超时）保存后立即生效</li><li>维护模式和登录限制等安全设置保存后，下一次登录时生效</li></ol>',43)])])}const p=r(d,[["render",i]]);export{m as __pageData,p as default};
